import random


def generate(seed: int = 0) -> list[str]:
    """All generated arguments stay within the statement bounds and follow the problem guarantees."""
    r = random.Random(seed)
    cases = [("hello world", "ad"), ("leet code", "e"), ("a b c", "")]
    seen = set(cases)
    while len(cases) < 600:
        text = " ".join(
            "".join(
                r.choice("abcdefghijklmnopqrstuvwxyz") for _ in range(r.randint(1, 10))
            )
            for _ in range(r.randint(1, 15))
        )
        broken = "".join(r.sample("abcdefghijklmnopqrstuvwxyz", r.randint(0, 15)))
        p = (text, broken)
        if p not in seen:
            seen.add(p)
            cases.append(p)
    return [f"candidate(text={t!r}, brokenLetters={b!r})" for t, b in cases]


_BASE_GENERATE = generate
_BOUNDARY_CALLS = [
    "candidate(text='', brokenLetters='abcdefghijklmnopqrstuvwxyz')"
]


def generate(seed: int = 0) -> list[str]:
    calls = _BASE_GENERATE(seed)
    return calls + [call for call in _BOUNDARY_CALLS if call not in calls]


_EXAMPLE_CALLS = ["candidate(text='leet code', brokenLetters='lt')"]

_PREVIOUS_GENERATE = generate


def generate(seed: int = 0) -> list[str]:
    calls = _PREVIOUS_GENERATE(seed)
    return calls + [call for call in _EXAMPLE_CALLS if call not in calls]
